package com.bank.core;

import java.util.logging.*;

public class OctalLiteralDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ─── BROKEN: would NOT compile ───
        // int bad = 09;   // ERROR: integer number too large / invalid octal digit '9'
        // int bad2 = 08;  // ERROR: same reason — 8 is not an octal digit either

        // ─── CORRECT: decimal 9 (no leading zero) ───
        int month = 9;
        log.info(() -> "Decimal 9 (no leading zero) = " + month);

        // ─── OCTAL that compiles but is a SILENT TRAP ───
        int octalSeven = 07;   // octal 7 == decimal 7 (coincidence)
        int octalTen   = 010;  // octal 10 == decimal 8 (SURPRISE — not 10!)
        int octalFifteen = 017; // octal 17 == decimal 15
        log.info(() -> "07  (octal) = " + octalSeven + " (decimal 7)");
        log.warning(() -> "010 (octal) = " + octalTen + " (decimal 8, NOT 10 — silent trap!)");
        log.info(() -> "017 (octal) = " + octalFifteen + " (decimal 15)");

        // If octal 9 was truly intended: 011 octal == decimal 9
        int octalNine = 011;
        log.info(() -> "011 (octal) = " + octalNine + " (decimal 9, the valid octal form)");

        // ─── Leading zeros in IDENTIFIERS must be String, never int ───
        String accountId = "0009876"; // preserves significant leading zeros
        log.info(() -> "Account number as String keeps leading zeros = " + accountId);
        // int accountIdInt = 0009876; // would be octal AND would lose leading zeros anyway

        // Underscores improve readability but do not change the base
        int oneMillion = 1_000_000; // decimal, readable
        log.info(() -> "Readable decimal with underscores = " + oneMillion);
    }
}
